1	// The executor's entry gate: identify the ONE dispatch this session was started
2	// for, and validate it in code BEFORE any model judgment (per-project-scheduling
3	// DESIGN §5.2). This is the CLI shell `validate-dispatch.mjs` was written to be
4	// driven by — it wires that pure core's `exists` / `isPackDeclared` / `loadTask`
5	// capabilities to this checkout and hands it the issue body.
6	//
7	// IT DOES NOT CLAIM. The claim protocol (read labels → swap ready → agent-running
8	// → post a claim comment → re-read, earliest claim wins) needs GitHub WRITES,
9	// which the executor session can only make through its MCP tools, so it stays
10	// agent-driven prose in executor.md. This shell only decides "is there a dispatch
11	// here, is it mine, and is it legal".
12	//
13	// TWO TRIGGER SOURCES, because the same `issues.labeled` webhook reaches an
14	// executor session by two different transports and only one of them was ever
15	// read here:
16	//
17	//   1. GITHUB ACTIONS writes the whole webhook payload to disk at
18	//      `$GITHUB_EVENT_PATH` — `action`, `label.name` and the entire `issue`
19	//      object, `issue.number` and `issue.body` included. Payload plus local
20	//      checkout is everything the validation needs, in one shot.
21	//   2. CLAUDE CODE ON THE WEB (CCR) delivers the same trigger as environment
22	//      variables instead — `CCR_TRIGGER_SOURCE`, `CCR_TRIGGER_EVENT`,
23	//      `CCR_TRIGGER_REPO`, `CCR_TRIGGER_ISSUE_NUMBER` — and writes no payload
24	//      file at all. It NAMES the issue but carries neither the label that was
25	//      added nor the body, so it resolves in two shots: this shell reports
26	//      `needs-issue` with the number, the executor fetches that one issue's body
27	//      and labels over MCP, and re-invokes with them (`--issue-body-file`,
28	//      `--issue-labels`) for the identical validation.
29	//
30	// Reading only source 1 is what made every CCR-run executor session miss its own
31	// trigger and select an issue by listing instead — the duplicate-execution bug
32	// re-entered through the front door. Observed live 2026-07-28: two sessions each
33	// selected dispatch #772 and claimed it one second apart.
34	//
35	// ZERO NETWORK, BY CONSTRUCTION — still. The executor session is MCP-only and
36	// carries no repo credential of its own, so anything reaching the GitHub REST API
37	// here would both fail to authenticate and trip the in-session-github-access
38	// rule. The CCR path does not change that: this shell never fetches the issue
39	// itself, it tells the EXECUTOR to fetch it over MCP and hand the bytes back.
40	//
41	// EXIT CODES ARE THE INTERFACE (see EXIT below). The executor branches on the
42	// number, so each verdict has its own code and its own documented next step:
43	//
44	//   0  valid       — a legal dispatch for this session's scope; go claim it.
45	//   10 invalid     — a forged or mangled dispatch. Comment the printed `reason`,
46	//                    remove the ready label, add `needs-human`, end the session.
47	//                    It never runs.
48	//   11 not-mine    — the trigger label is the OTHER executor's ready label, is no
49	//                    ready label at all, or the issue no longer carries one (a
50	//                    dispatch another session has already claimed). Stop. Change
51	//                    nothing, comment nothing.
52	//   13 needs-issue — a CCR trigger named the issue but carries no body/labels.
53	//                    Fetch THAT issue over MCP and re-invoke with them.
54	//   12 no-trigger  — NO source names an issue. STOP THE SESSION. There is no
55	//                    fallback: never select a dispatch by listing (see below).
56	//   2  usage       — bad invocation (an unknown scope argument, an unreadable
57	//                    `--issue-body-file`).
58	//   1  internal    — an unexpected fault in this shell.
59	//
60	// THERE IS NO FALLBACK, BY DESIGN. Exit 12 used to send the executor off to list
61	// the open dispatches and take the oldest. That is precisely the
62	// N-sessions-racing-over-N-issues failure the one-session-one-issue rule exists to
63	// prevent, reached from the other direction: one scheduler run files every due
64	// dispatch seconds apart, so every session that cannot name its own trigger builds
65	// the SAME work list and races over it. A session that does not know its issue
66	// must run nothing — the scheduler re-arms an unrun dispatch on its next hourly
67	// pass, so stopping costs a delay while guessing costs duplicated work.
68	//
69	// Usage: `node <engine>/scheduler/resolve-dispatch.mjs [self|fleet]`
70	//                `[--issue-body-file <path>] [--issue-labels <csv>]`
71	// The positional argument is THIS SESSION's scope — which of the two executor
72	// routines is running. It defaults to `self`, which is every ordinary project's
73	// executor; the FLEET routine must pass `fleet` explicitly, and a fleet payload
74	// arriving at a session that did not is reported as not-mine with that stated
75	// plainly. The two flags carry what a CCR trigger cannot, and are ignored on the
76	// Actions path (whose payload already has both).
77	
78	import { existsSync, readFileSync } from 'node:fs';
79	import { dirname, join, sep } from 'node:path';
80	import { fileURLToPath, pathToFileURL } from 'node:url';
81	import { DISPATCH_PATH_RE, dispatchFirstLine, validateDispatchBody } from './validate-dispatch.mjs';
82	import { readyLabelForScope } from './dispatch.mjs';
83	import { SESSION_SCOPES } from './task-contract.mjs';
84	import { SHARED_SUBDIR } from '../pack_loader/pack-registry.mjs';
85	
86	export const EXIT = {
87	  ok: 0,
88	  internal: 1,
89	  usage: 2,
90	  invalid: 10,
91	  notMine: 11,
92	  noTrigger: 12,
93	  needsIssue: 13,
94	};
95	
96	// The executor scope a ready label implies — the exact inverse of the mapping the
97	// SCHEDULER files a dispatch under (`readyLabelForScope`), derived from it rather
98	// than restated, so the two can never drift. `null` = not a ready label at all.
99	export const scopeForLabel = (label) =>
100	  SESSION_SCOPES.find((scope) => readyLabelForScope(scope) === label) ?? null;
101	
102	// Which checkout do the task paths in a dispatch body resolve against? Answered
103	// from where THIS engine copy is mounted, not from cwd — a consumer runs the
104	// vendored engine at `<root>/.claudinite/shared/engine/scheduler/`, the canon
105	// repo runs its own at `<root>/engine/scheduler/` (executor.md, "Engine command
106	// paths"). Deriving it from the module's own location means whichever copy the
107	// executor invoked resolves against that copy's own repo, with nothing to pass.
108	const MOUNT_SUFFIX = sep + SHARED_SUBDIR;
109	export function repoRootFrom(moduleUrl) {
110	  const home = dirname(dirname(dirname(fileURLToPath(moduleUrl)))); // <home>/engine/scheduler/<this file>
111	  return home.endsWith(MOUNT_SUFFIX) ? home.slice(0, -MOUNT_SUFFIX.length) : home;
112	}
113	
114	// Read the webhook payload the label event was started with. Every way of not
115	// having one collapses to a single `{ error }` — unset, unreadable, unparsable —
116	// because the caller's response to all of them is the same: try the other
117	// trigger source, and stop the session if that names no issue either.
118	export function readEventPayload(env = process.env, read = (p) => readFileSync(p, 'utf8')) {
119	  const path = env.GITHUB_EVENT_PATH;
120	  if (!path) return { error: 'GITHUB_EVENT_PATH is not set — this session has no event payload on disk' };
121	  let raw;
122	  try {
123	    raw = read(path);
124	  } catch (e) {
125	    return { error: `GITHUB_EVENT_PATH points at ${path}, which is unreadable: ${e.message}` };
126	  }
127	  let event;
128	  try {
129	    event = JSON.parse(raw);
130	  } catch (e) {
131	    return { error: `the event payload at ${path} is not valid JSON: ${e.message}` };
132	  }
133	  if (event === null || typeof event !== 'object' || Array.isArray(event)) {
134	    return { error: `the event payload at ${path} is not an event object` };
135	  }
136	  return { event };
137	}
138	
139	// The three facts a dispatch trigger must carry. Anything short of all three
140	// means the payload cannot name this session's issue — not a rejection of a
141	// dispatch, just this source failing to identify one; the caller tries the other
142	// source before giving up.
143	export function triggerFromEvent(event) {
144	  const action = event.action;
145	  const label = event.label?.name;
146	  const number = event.issue?.number;
147	  if (action !== 'labeled') return { error: `the event payload is a "${action}" event, not a label event — it names no dispatch` };
148	  if (typeof label !== 'string' || label === '') return { error: 'the label event carries no label.name' };
149	  if (!Number.isInteger(number)) return { error: 'the label event carries no issue.number' };
150	  return { trigger: { source: 'payload', label, number, body: event.issue?.body ?? '' } };
151	}
152	
153	// The CCR trigger: same webhook, delivered as environment variables by Claude
154	// Code on the web, which writes no payload file. It names the issue and nothing
155	// else — no `label.name`, no `issue.body` — so the trigger it yields is
156	// deliberately PARTIAL, and `main` turns that into the two-shot `needs-issue`
157	// handshake rather than guessing either missing field.
158	export function triggerFromCcrEnv(env = process.env) {
159	  const source = env.CCR_TRIGGER_SOURCE;
160	  const event = env.CCR_TRIGGER_EVENT;
161	  const raw = env.CCR_TRIGGER_ISSUE_NUMBER;
162	  if (!source && !event && !raw) return { error: 'no CCR_TRIGGER_* variables are set either — this session carries no CCR trigger' };
163	  if (source !== 'github') return { error: `CCR_TRIGGER_SOURCE is ${JSON.stringify(source ?? null)}, not "github" — this session was not started by a GitHub event` };
164	  if (event !== 'issues.labeled') return { error: `CCR_TRIGGER_EVENT is ${JSON.stringify(event ?? null)}, not "issues.labeled" — it names no dispatch` };
165	  const number = Number(raw);
166	  if (!raw || !Number.isInteger(number) || number <= 0) return { error: `CCR_TRIGGER_ISSUE_NUMBER is ${JSON.stringify(raw ?? null)}, which is not an issue number` };
167	  return { trigger: { source: 'ccr', number, repo: env.CCR_TRIGGER_REPO ?? '' } };
168	}
169	
170	// Identify this session's ONE dispatch from whichever transport carried it.
171	// Order is preference, not precedence-by-truth: the Actions payload is tried
172	// first only because it answers in one shot, and a session that somehow has both
173	// gets the same issue from either. Every failure of both sources is collected
174	// into one reason, because the executor prints it and then stops.
175	export function resolveTrigger(env = process.env, read) {
176	  const reasons = [];
177	  const { event, error: payloadError } = readEventPayload(env, read);
178	  if (payloadError) reasons.push(payloadError);
179	  else {
180	    const { trigger, error } = triggerFromEvent(event);
181	    if (trigger) return { trigger };
182	    reasons.push(error);
183	  }
184	  const { trigger: ccr, error: ccrError } = triggerFromCcrEnv(env);
185	  if (ccr) return { trigger: ccr };
186	  reasons.push(ccrError);
187	  return { error: reasons.join('; ') };
188	}
189	
190	// `[scope] [--flag value|--flag=value]`. Kept deliberately tiny — the shell takes
191	// one positional and two flags, and a dependency-free parser is less surface than
192	// the alternative.
193	export function parseArgs(argv) {
194	  const positional = [];
195	  const flags = {};
196	  for (let i = 0; i < argv.length; i++) {
197	    const arg = argv[i];
198	    if (!arg.startsWith('--')) { positional.push(arg); continue; }
199	    const eq = arg.indexOf('=');
200	    if (eq !== -1) flags[arg.slice(2, eq)] = arg.slice(eq + 1);
201	    else flags[arg.slice(2)] = argv[++i] ?? '';
202	  }
203	  return { positional, flags };
204	}
205	
206	// Which of the issue's CURRENT labels is a ready label? On the CCR path this
207	// stands in for the `label.name` the trigger never carried — and it is strictly
208	// more informative than the event's: a dispatch another session already claimed
209	// no longer carries a ready label at all, so this catches the lost race here at
210	// step 1 rather than at the claim.
211	export function readyLabelAmong(labels) {
212	  const ready = labels.filter((l) => scopeForLabel(l) !== null);
213	  if (ready.length === 0) return { error: `it carries no ready label (it has: ${labels.join(', ') || 'none'}) — its dispatch has already been claimed or converged by another session` };
214	  if (ready.length > 1) return { error: `it carries more than one ready label (${ready.join(', ')}), so which executor owns it is ambiguous` };
215	  return { label: ready[0] };
216	}
217	
218	// The block the executor reads. `key: value` lines, one fact per line: an agent
219	// quoting a field back must not have to parse prose, and a reader diffing two
220	// runs must see exactly what changed.
221	const block = (fields) => Object.entries(fields).map(([k, v]) => `${k}: ${v}`).join('\n');
222	
223	function done(code, fields, advice) {
224	  console.log(block(fields));
225	  if (advice) console.error(`resolve-dispatch: ${advice}`);
226	  process.exit(code);
227	}
228	
229	async function main() {
230	  const { positional, flags } = parseArgs(process.argv.slice(2));
231	  const scopeGiven = positional.length > 0;
232	  const scope = positional[0] ?? 'self';
233	  if (!SESSION_SCOPES.includes(scope)) {
234	    console.error(`resolve-dispatch: unknown scope "${scope}" — usage: node resolve-dispatch.mjs [${SESSION_SCOPES.join('|')}] [--issue-body-file <path>] [--issue-labels <csv>]`);
235	    process.exit(EXIT.usage);
236	  }
237	
238	  const { trigger, error: triggerError } = resolveTrigger();
239	  if (triggerError) {
240	    done(EXIT.noTrigger, { dispatch: 'no-trigger', scope, reason: triggerError },
241	      `${triggerError}. No trigger source names an issue, so this session cannot know which dispatch it was started for. STOP: run nothing, change nothing, comment nothing, end the session. There is NO fallback — never pick an issue by listing ${readyLabelForScope(scope)}; every dispatch in that list already has its own session, and the scheduler re-arms an unrun one on its next hourly pass.`);
242	  }
243	
244	  let { label, number, body } = trigger;
245	
246	  // The CCR handshake: the trigger named the issue, the executor fetched it over
247	  // MCP, and hands back here the two fields the environment could not carry.
248	  if (trigger.source === 'ccr') {
249	    const bodyFile = flags['issue-body-file'];
250	    const labelsCsv = flags['issue-labels'];
251	    if (bodyFile === undefined || labelsCsv === undefined) {
252	      done(EXIT.needsIssue, { dispatch: 'needs-issue', issue: number, scope, source: 'ccr', repo: trigger.repo || '(unset)' },
253	        `the CCR trigger names issue #${number} but carries neither its body nor its labels. Fetch ISSUE #${number} ALONE over MCP (its body and its current labels), write the body verbatim to a file, then re-run: node <engine>/scheduler/resolve-dispatch.mjs ${scope} --issue-body-file <path> --issue-labels <comma-separated current labels>. Do not list, select, or touch any other issue.`);
254	    }
255	    try {
256	      body = readFileSync(bodyFile, 'utf8');
257	    } catch (e) {
258	      console.error(`resolve-dispatch: --issue-body-file ${bodyFile} is unreadable: ${e.message}`);
259	      process.exit(EXIT.usage);
260	    }
261	    const labels = labelsCsv.split(',').map((l) => l.trim()).filter(Boolean);
262	    const { label: ready, error: labelError } = readyLabelAmong(labels);
263	    if (labelError) {
264	      done(EXIT.notMine, { dispatch: 'not-mine', issue: number, scope, labels: labels.join('|') || '(none)' },
265	        `issue #${number}: ${labelError}. Stop: change nothing, comment nothing.`);
266	    }
267	    label = ready;
268	  }
269	
270	  const labelScope = scopeForLabel(label);
271	  if (labelScope === null) {
272	    done(EXIT.notMine, { dispatch: 'not-mine', issue: number, scope, label },
273	      `issue #${number} was labeled "${label}", which is not a ready label — this is not an executor dispatch. Stop: change nothing, comment nothing.`);
274	  }
275	  if (labelScope !== scope) {
276	    done(EXIT.notMine, { dispatch: 'not-mine', issue: number, scope, label, labelScope },
277	      `issue #${number} is labeled "${label}", a ${labelScope}-scoped dispatch, but this session's scope is "${scope}"${scopeGiven ? '' : ' (the default — pass "fleet" if this IS the fleet executor)'}. It is the other executor's to run and it already has a session. Stop: change nothing, comment nothing.`);
278	  }
279	
280	  // The checkout the dispatch's task path must resolve in. `exists` reads the
281	  // working tree; in an executor session that IS HEAD (a fresh checkout, nothing
282	  // written yet), which is what validate-dispatch means by "exists at HEAD".
283	  const root = process.env.CLAUDINITE_REPO_ROOT || repoRootFrom(import.meta.url);
284	  const { loadConfig } = await import('../checks/helpers/repo-context.mjs');
285	  const declared = new Set(loadConfig(root).packs);
286	
287	  // `loadTask` is SYNCHRONOUS by design — it keeps validate-dispatch's core pure
288	  // and sync-testable — but importing an .mjs is not, so the shell prefetches the
289	  // module here and the capability just replays the result (or rethrows the parse
290	  // failure, which is exactly what the core wants to report).
291	  const firstLine = dispatchFirstLine(body);
292	  const mjsRelative = firstLine.replace(/task\.md$/, 'task.mjs');
293	  let loaded = null;
294	  let loadError = null;
295	  if (DISPATCH_PATH_RE.test(firstLine) && existsSync(join(root, mjsRelative))) {
296	    try {
297	      loaded = (await import(pathToFileURL(join(root, mjsRelative)).href)).default;
298	    } catch (e) {
299	      loadError = e;
300	    }
301	  }
302	
303	  const verdict = validateDispatchBody(body, {
304	    exists: (p) => existsSync(join(root, p)),
305	    isPackDeclared: (id) => declared.has(id),
306	    loadTask: () => { if (loadError) throw loadError; return loaded; },
307	  });
308	
309	  if (!verdict.ok) {
310	    done(EXIT.invalid, { dispatch: 'invalid', issue: number, scope, label, reason: verdict.reason },
311	      `issue #${number} is not a valid dispatch: ${verdict.reason}. It must not run — comment naming what failed, remove the "${label}" label, add "needs-human", and end the session.`);
312	  }
313	
314	  done(EXIT.ok, {
315	    dispatch: 'valid',
316	    issue: number,
317	    scope,
318	    label,
319	    source: trigger.source,
320	    taskPath: verdict.taskPath,
321	    pack: verdict.pack,
322	    task: verdict.task,
323	    model: verdict.model,
324	    resolvedModel: verdict.resolvedModel,
325	    outcome: verdict.outcome,
326	    executionTimeout: verdict.executionTimeout ?? 'none',
327	  });
328	}
329	
330	// Run only when invoked directly (the executor's `node resolve-dispatch.mjs`),
331	// never on import — the exported helpers above are unit-testable without it.
332	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
333	  main().catch((e) => { console.error(`resolve-dispatch: ${e.stack || e}`); process.exit(EXIT.internal); });
334	}
